SELECT mu.id AS userId, mu.nickname, mu.avatar_url, mu.last_login_ip, muf.create_time AS attentionTime FROM member_user_follow muf INNER JOIN member_user mu ON muf.user_id = mu.id
AND muf.status = 0 AND muf.target_type = 1 AND muf.target_id = #{reqVO.authorId}
AND NOT EXISTS ( SELECT 1 FROM author_member_tag_relation amtr_exclude WHERE amtr_exclude.user_id = muf.user_id AND amtr_exclude.author_id = #{reqVO.authorId} AND amtr_exclude.tag_id = #{reqVO.tagId} AND amtr_exclude.deleted = 0 )
AND mu.nickname LIKE CONCAT('%', #{reqVO.fansName}, '%')
AND muf.create_time >= #{reqVO.beginTime}
AND muf.create_time <= #{reqVO.endTime}

SELECT mu.id AS user_id, mu.nickname, mu.avatar_url, mu.last_login_ip, muf.create_time AS attentionTime, muf.user_status AS userStatus FROM member_user_follow muf INNER JOIN member_user mu ON muf.user_id = mu.id
INNER JOIN author_member_tag_relation amtr ON muf.user_id = amtr.user_id AND amtr.author_id = #{reqVO.authorId} AND amtr.deleted = 0
AND muf.status = 0 AND muf.target_type = 1 AND muf.target_id = #{reqVO.authorId}
AND amtr.tag_id = #{reqVO.tagId}
AND muf.user_status = #{reqVO.userStatus}
AND mu.nickname LIKE CONCAT('%', #{reqVO.fansName}, '%')
AND muf.create_time >= #{reqVO.beginTime}
AND muf.create_time <= #{reqVO.endTime}

SELECT mu.id AS user_id, mu.nickname, mu.avatar_url, mu.last_login_ip, muf.create_time AS attentionTime, muf.user_status AS userStatus FROM member_user_follow muf INNER JOIN member_user mu ON muf.user_id = mu.id
AND muf.status = 0 AND muf.target_type = 1 AND muf.target_id = #{reqVO.authorId} AND NOT EXISTS ( SELECT 1 FROM author_member_tag_relation amtr WHERE amtr.user_id = muf.user_id AND amtr.author_id = #{reqVO.authorId} AND amtr.deleted = 0 )
AND muf.user_status = #{reqVO.userStatus}
