AND muf.create_time <= #{reqVO.endTime}

SELECT
mu.id AS user_id,
mu.nickname,
mu.avatar_url
FROM author_member_tag_relation amtr
INNER JOIN member_user mu ON amtr.user_id = mu.id
inner JOIN member_user_follow muf ON muf.user_id = mu.id and amtr.author_id = muf.target_id

    AND amtr.tag_id = #{tagId}
    AND amtr.author_id = #{authorId}
    and amtr.deleted = 0
    AND muf.status = 0

        AND muf.create_time >= #{beginTime}


        AND muf.create_time <= #{endTime}
